DROP TABLE IF EXISTS `pharma_concerner_view`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `pharma_concerner_view` AS select `conc`.`quantite` AS `quantite`,`conc`.`prixUnit` AS `prixUnit`,`conc`.`reduction` AS `reduction`,`ven`.`reference` AS `reference`,`ven`.`prixPercu` AS `prixPercu`,`ven`.`prixTotal` AS `prixTotal`,`en_r`.`prixAchat` AS `prixAchat`,`en_r`.`prixVente` AS `prixVente`,`en_r`.`dateLivraison` AS `dateLivraison`,`en_r`.`datePeremption` AS `datePeremption`,`en_r`.`quantite` AS `quantite_rayon`,`en_r`.`quantiteRestante` AS `quantiteRestante`,`pdt`.`nom` AS `nom`,`ven`.`dateVente` AS `dateVente` from (((`concerner` `conc` join `vente` `ven` on((`conc`.`vente_id` = `ven`.`id`))) join `en_rayon` `en_r` on((`conc`.`en_rayon_id` = `en_r`.`id`))) join `produit` `pdt` on((`pdt`.`id` = `en_r`.`produit_id`)));

