CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `pharma_en_rayon_without_cmd_view` AS select `en_r`.`prixAchat` AS `prixAchat`,`en_r`.`prixVente` AS `prixVente`,`en_r`.`dateLivraison` AS `dateLivraison`,`en_r`.`datePeremption` AS `datePeremption`,`en_r`.`quantite` AS `quantite`,`en_r`.`quantiteRestante` AS `quantiteRestante`,`pd`.`nom` AS `nom` from (`en_rayon` `en_r` join `produit` `pd` on((`en_r`.`produit_id` = `pd`.`id`)));

