DROP TABLE IF EXISTS `pharma_produit_commande_view`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `pharma_produit_commande_view` AS select `pdt`.`nom` AS `nom`,`pdt`.`ean13` AS `ean13`,`pdt_cmd`.`puCmd` AS `puCmd`,`pdt_cmd`.`ptCmd` AS `ptCmd`,`pdt_cmd`.`qtiteCmd` AS `qtiteCmd`,`pdt_cmd`.`etat` AS `etat`,`cmd`.`ref` AS `ref`,`four`.`nom` AS `fournisseurName`,`cmd`.`montantCmd` AS `montantCmd`,`cmd`.`montantRecu` AS `montantRecu`,`cmd`.`dateCreation` AS `dateCreation`,`cmd`.`dateLivraison` AS `dateLivraison` from (((`produit_cmd` `pdt_cmd` join `commande` `cmd` on((`pdt_cmd`.`commande_id` = `cmd`.`id`))) join `produit` `pdt` on((`pdt`.`id` = `pdt_cmd`.`produit_id`))) join `fournisseur` `four` on((`four`.`id` = `cmd`.`fournisseur_id`)));

DROP TABLE IF EXISTS `pharma_produit_view`;
